#!/usr/bin/env python3
"""CSV Insights: small, dependency-free CSV filtering and aggregation CLI."""

from __future__ import annotations

import argparse
import csv
import json
import sys
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import Sequence


def fail(message: str) -> None:
    raise ValueError(message)


def parse_filter(value: str) -> tuple[str, str]:
    if "=" not in value:
        fail(f"malformed filter {value!r}; expected COLUMN=VALUE")
    column, expected = value.split("=", 1)
    if not column:
        fail(f"malformed filter {value!r}; column must not be empty")
    return column, expected


def parse_args(argv: Sequence[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Filter and aggregate RFC-4180 CSV files.")
    parser.add_argument("input", help="input CSV file (never modified)")
    parser.add_argument("--where", action="append", default=[], metavar="COLUMN=VALUE")
    parser.add_argument("--group-by", metavar="COLUMN")
    parser.add_argument("--sum", dest="sum_column", metavar="COLUMN")
    parser.add_argument("--avg", dest="avg_column", metavar="COLUMN")
    parser.add_argument("--output", choices=("json", "csv"), default="json")
    args = parser.parse_args(argv)
    if (args.sum_column or args.avg_column) and not args.group_by:
        parser.error("--sum and --avg require --group-by")
    return args


def read_csv(path: str) -> tuple[list[str], list[dict[str, str]]]:
    try:
        with Path(path).open("r", encoding="utf-8-sig", newline="") as source:
            reader = csv.reader(source, strict=True)
            try:
                headers = next(reader)
            except StopIteration:
                fail("input CSV is empty")
            if not headers or any(header == "" for header in headers):
                fail("CSV headers must be non-empty")
            if len(set(headers)) != len(headers):
                fail("CSV headers must be unique")
            rows: list[dict[str, str]] = []
            for row_number, values in enumerate(reader, start=2):
                if len(values) != len(headers):
                    fail(
                        f"row {row_number} has {len(values)} fields; expected {len(headers)}"
                    )
                rows.append(dict(zip(headers, values)))
            return headers, rows
    except (OSError, csv.Error) as error:
        fail(f"cannot read CSV: {error}")


def decimal_cell(value: str, row_number: int, column: str) -> Decimal:
    if value == "":
        fail(f"invalid numeric value at row {row_number}, column {column!r}: blank")
    try:
        number = Decimal(value)
    except InvalidOperation:
        fail(f"invalid numeric value at row {row_number}, column {column!r}: {value!r}")
    if not number.is_finite():
        fail(f"invalid numeric value at row {row_number}, column {column!r}: {value!r}")
    return number


def format_decimal(value: Decimal) -> str:
    text = format(value, "f")
    if "." in text:
        text = text.rstrip("0").rstrip(".")
    return "0" if text in ("", "-0") else text


def aggregate(rows: list[dict[str, str]], group: str, sum_column: str | None,
              avg_column: str | None, headers: list[str]) -> tuple[list[str], list[dict[str, str]]]:
    totals: dict[str, dict[str, Decimal | int]] = {}
    for index, row in enumerate(rows, start=2):
        key = row[group]
        state = totals.setdefault(key, {"count": 0, "sum": Decimal(0), "avg": Decimal(0)})
        state["count"] = int(state["count"]) + 1
        if sum_column:
            state["sum"] = Decimal(state["sum"]) + decimal_cell(row[sum_column], index, sum_column)
        if avg_column:
            state["avg"] = Decimal(state["avg"]) + decimal_cell(row[avg_column], index, avg_column)

    result_headers = [group]
    if sum_column:
        result_headers.append(f"sum_{sum_column}")
    if avg_column:
        result_headers.append(f"avg_{avg_column}")
    result: list[dict[str, str]] = []
    for key in sorted(totals):
        state = totals[key]
        item = {group: key}
        if sum_column:
            item[f"sum_{sum_column}"] = format_decimal(Decimal(state["sum"]))
        if avg_column:
            item[f"avg_{avg_column}"] = format_decimal(
                Decimal(state["avg"]) / int(state["count"])
            )
        result.append(item)
    return result_headers, result


def emit(headers: list[str], rows: list[dict[str, str]], output: str) -> None:
    if output == "json":
        json.dump(rows, sys.stdout, ensure_ascii=False, separators=(",", ":"))
        sys.stdout.write("\n")
    else:
        writer = csv.DictWriter(sys.stdout, fieldnames=headers, lineterminator="\n")
        writer.writeheader()
        writer.writerows(rows)


def main(argv: Sequence[str] | None = None) -> int:
    try:
        args = parse_args(sys.argv[1:] if argv is None else argv)
        headers, rows = read_csv(args.input)
        filters = [parse_filter(value) for value in args.where]
        requested = [column for column, _ in filters]
        requested += [column for column in (args.group_by, args.sum_column, args.avg_column) if column]
